import csv, json, re
schema=json.load(open('schema.json'))
with open('data.csv', newline='') as f:
    reader=csv.reader(f); headers=next(reader); rows=list(reader)
idx={name:i for i,name in enumerate(headers)}
viol=[]
def add(c,row,rule,value,message): viol.append({'column':c,'row':row,'rule':rule,'value':value,'message':message})
rule_order=['type','required','min','max','pattern','enum','unique']
for c in headers:
    spec=schema['columns'].get(c)
    if spec is None:
        if schema.get('strict',False): add(c,None,'strict',None,'column "'+c+'" not defined in schema')
        continue
    vals=[row[idx[c]] for row in rows]
    for ri,v in enumerate(vals,1):
        if v and spec['type']=='int':
            try: int(v,10)
            except ValueError: add(c,ri,'type',v,'expected int, got "'+v+'"')
        if v and spec['type']=='float':
            try: float(v)
            except ValueError: add(c,ri,'type',v,'expected float, got "'+v+'"')
        if v and spec['type']=='string' and 'pattern' in spec and not re.search(spec['pattern'],v): add(c,ri,'pattern',v,'value "'+v+'" does not match pattern '+spec['pattern'])
        if not v and spec.get('required',False): add(c,ri,'required',None,'value is required')
        if v and spec['type'] in ('int','float'):
            try: num=float(v)
            except ValueError: num=None
            if num is not None and 'min' in spec and num<spec['min']: add(c,ri,'min',v,'value '+v+' is below minimum '+str(spec['min']))
            if num is not None and 'max' in spec and num>spec['max']: add(c,ri,'max',v,'value '+v+' exceeds maximum '+str(spec['max']))
        if v and 'enum' in spec and v not in spec['enum']: add(c,ri,'enum',v,'value "'+v+'" is not in allowed values ['+', '.join(spec['enum'])+']')
    if spec.get('unique',False):
        first={}
        for ri,v in enumerate(vals,1):
            if v and v in first: add(c,ri,'unique',v,'duplicate value "'+v+'" (first at row '+str(first[v])+', repeated at row '+str(ri)+')')
            elif v: first[v]=ri
for c,spec in schema['columns'].items():
    if c not in idx: add(c,None,'column_missing',None,'column "'+c+'" defined in schema but missing from data')
rank={r:i for i,r in enumerate(rule_order+['column_missing','strict'])}
header_order={c:i for i,c in enumerate(headers)}
missing_order={c:i for i,c in enumerate(schema['columns'])}
def key(v): return (header_order.get(v['column'],len(headers)+missing_order.get(v['column'],0)),rank[v['rule']],(1,0) if v['row'] is None else (0,v['row']))
viol.sort(key=key)
print(json.dumps({'exit':0,'valid':len(viol)==0,'violations':viol,'summary':{'total_violations':len(viol),'columns_checked':sum(1 for c in schema['columns'] if c in idx),'rows_checked':len(rows)}}))

