    if e and '@' not in e: add('email',i,'pattern',e,'value "'+e+'" does not match pattern ^[^@]+@[^@]+$')
    s=row['status']
    if s and s not in ['active','inactive']: add('status',i,'enum',s,'value "'+s+'" is not in allowed values [active, inactive]')
first={}
for i,row in enumerate(rows,1):
    e=row['email']
    if e in first and e: add('email',i,'unique',e,'duplicate value "'+e+'" (first at row '+str(first[e])+', repeated at row '+str(i)+')')
    elif e: first[e]=i
add('missing',None,'column_missing',None,'column "missing" defined in schema but missing from data')
add('extra',None,'strict',None,'column "extra" not defined in schema')
print(json.dumps({'violations':viol,'summary':{'total_violations':len(viol),'columns_checked':3,'rows_checked':5}}))

